import java.util.*;

class Solution {
    public List<String> restoreIpAddresses(String s) {
        List<String> result = new ArrayList<>();
        if (s.length() < 4 || s.length() > 12) {
            return result;
        }
        backtrack(s, 0, new ArrayList<>(), result);
        return result;
    }

    private void backtrack(String s, int index, List<String> parts, List<String> result) {
        if (parts.size() == 4) {
            if (index == s.length()) {
                result.add(String.join(".", parts));
            }
            return;
        }

        int remainingParts = 4 - parts.size();
        int remainingChars = s.length() - index;
        if (remainingChars < remainingParts || remainingChars > remainingParts * 3) {
            return;
        }

        for (int length = 1; length <= 3 && index + length <= s.length(); length++) {
            String segment = s.substring(index, index + length);
            if (!isValidSegment(segment)) {
                continue;
            }
            parts.add(segment);
            backtrack(s, index + length, parts, result);
            parts.remove(parts.size() - 1);
        }
    }

    private boolean isValidSegment(String segment) {
        if (segment.length() > 1 && segment.charAt(0) == '0') {
            return false;
        }
        return Integer.parseInt(segment) <= 255;
    }
}

import java.util.*;

class Solution {
    public List<String> restoreIpAddresses(String s) {
        List<String> result = new ArrayList<>();
        int n = s.length();
        if (n < 4 || n > 12) {
            return result;
        }

        for (int firstLength = 1; firstLength <= 3; firstLength++) {
            for (int secondLength = 1; secondLength <= 3; secondLength++) {
                for (int thirdLength = 1; thirdLength <= 3; thirdLength++) {
                    int fourthLength = n - firstLength - secondLength - thirdLength;
                    if (fourthLength < 1 || fourthLength > 3) {
                        continue;
                    }

                    int firstEnd = firstLength;
                    int secondEnd = firstEnd + secondLength;
                    int thirdEnd = secondEnd + thirdLength;
                    String first = s.substring(0, firstEnd);
                    String second = s.substring(firstEnd, secondEnd);
                    String third = s.substring(secondEnd, thirdEnd);
                    String fourth = s.substring(thirdEnd);
                    if (isValidSegment(first) && isValidSegment(second)
                            && isValidSegment(third) && isValidSegment(fourth)) {
                        result.add(first + "." + second + "." + third + "." + fourth);
                    }
                }
            }
        }
        return result;
    }

    private boolean isValidSegment(String segment) {
        if (segment.length() > 1 && segment.charAt(0) == '0') {
            return false;
        }
        int value = Integer.parseInt(segment);
        return value <= 255;
    }
}

import java.util.*;

class Solution {
    private static class State {
        int index;
        int parts;
        String address;

        State(int index, int parts, String address) {
            this.index = index;
            this.parts = parts;
            this.address = address;
        }
    }

    public List<String> restoreIpAddresses(String s) {
        List<String> result = new ArrayList<>();
        if (s.length() < 4 || s.length() > 12) {
            return result;
        }

        Queue<State> queue = new ArrayDeque<>();
        queue.offer(new State(0, 0, ""));

        while (!queue.isEmpty()) {
            State state = queue.poll();
            if (state.parts == 4) {
                if (state.index == s.length()) {
                    result.add(state.address);
                }
                continue;
            }

            int remainingParts = 4 - state.parts;
            int remainingChars = s.length() - state.index;
            for (int length = 1; length <= 3 && state.index + length <= s.length(); length++) {
                int after = remainingChars - length;
                if (after < remainingParts - 1 || after > (remainingParts - 1) * 3) {
                    continue;
                }
                String segment = s.substring(state.index, state.index + length);
                if (!isValidSegment(segment)) {
                    continue;
                }
                String nextAddress = state.address.isEmpty() ? segment : state.address + "." + segment;
                queue.offer(new State(state.index + length, state.parts + 1, nextAddress));
            }
        }
        return result;
    }

    private boolean isValidSegment(String segment) {
        if (segment.length() > 1 && segment.charAt(0) == '0') {
            return false;
        }
        return Integer.parseInt(segment) <= 255;
    }
}

import java.util.*;

class Solution {
    public List<String> restoreIpAddresses(String s) {
        int n = s.length();
        if (n < 4 || n > 12) {
            return new ArrayList<>();
        }

        List<String>[][] dp = new ArrayList[n + 1][5];
        for (int i = 0; i <= n; i++) {
            for (int parts = 0; parts <= 4; parts++) {
                dp[i][parts] = new ArrayList<>();
            }
        }
        dp[0][0].add("");

        for (int parts = 0; parts < 4; parts++) {
            for (int index = 0; index <= n; index++) {
                if (dp[index][parts].isEmpty()) {
                    continue;
                }
                for (int length = 1; length <= 3 && index + length <= n; length++) {
                    String segment = s.substring(index, index + length);
                    if (!isValidSegment(segment)) {
                        continue;
                    }
                    for (String prefix : dp[index][parts]) {
                        String address = prefix.isEmpty() ? segment : prefix + "." + segment;
                        dp[index + length][parts + 1].add(address);
                    }
                }
            }
        }

        return dp[n][4];
    }

    private boolean isValidSegment(String segment) {
        if (segment.length() > 1 && segment.charAt(0) == '0') {
            return false;
        }
        return Integer.parseInt(segment) <= 255;
    }
}
